function sparkPath(cs) {
  // single-series sparkline for a KPI header
  const s = slice();
  const values = s.map(r => sum(r, cs));
  const min = Math.min(...values), max = Math.max(...values);
  const span = (max - min) || 1;
  const W = 180, H = 34;
  const pts = values.map((v, i) => {
    const x = 3 + i * ((W - 6) / (values.length - 1 || 1));
    const y = H - 4 - ((v - min) / span) * (H - 8);
    return `${x.toFixed(1)},${y.toFixed(1)}`;
  }).join(' ');
  return `<svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" aria-hidden="true">
    <polyline fill="none" stroke="var(--series-1)" stroke-width="2" stroke-linejoin="round" stroke-linecap="round" points="${pts}"/>
  </svg>`;
}

function kpiCard(label, value, pct, note, spark) {
  return `<div class="kpi">
    <div class="kpi-label">${label}</div>
    <div class="kpi-value">${value}</div>
    <div class="kpi-delta"><b>${pct>=0?'▲':'▼'} ${Math.abs(pct).toFixed(1)}%</b> vs prior period</div>
    <div class="kpi-note" style="font-size:12px;color:var(--muted)">${note}</div>
    ${spark ? spark : ''}
  </div>`;
}

