// Minimal DOM stub
const store={};
function el(id){ return store[id] ||= {innerHTML:'',textContent:'',style:{},setAttribute(){},classList:{toggle(){},add(){},remove(){}},querySelectorAll:()=>[],addEventListener(){},appendChild(){},querySelector:()=>null}; }
